def get_profiling_params(self, request: Request, project: Project) -> Dict[str, Any]:
    try:
        params: Dict[str, Any] = parse_profile_filters(request.query_params.get("query", ""))
    except InvalidSearchQuery as err:
        raise ParseError(detail=str(err))

    params.update(self.get_filter_params(request, project))

    return params

@abstractmethod
def get_data_fn(self, request: Request, project: Project, kwargs: Dict[str, Any]) -> Any:
    raise NotImplementedError

def proxy_profiling_service(
    method: str,
    path: str,
    params: Optional[Dict[str, Any]] = None,
    headers: Optional[Dict[str, str]] = None,
) -> HttpResponse:
    profiling_response = get_from_profiling_service(method, path, params=params, headers=headers)
    return HttpResponse(
        content=profiling_response.data,
        status=profiling_response.status,
        content_type=profiling_response.headers.get("Content-Type", "application/json"),
    )
